def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    cindy_like = False
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 110:
                cindy_like = True

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 8.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    low_comp = 0
    for b in prev_bids:
        if b <= 45:
            low_comp += 1

    emergency = hp <= 3 or no_water >= 2
    danger = hp <= 5 or no_water >= 1
    tight_supply = supply <= 17
    ample_supply = supply >= 22

    if emergency:
        if cindy_like:
            bid = min(budget, 118.0)
        else:
            bid = min(budget, max(62.0, highest_prev + 4.0, DAILY_SALARY * 0.95))
        return float(max(0.0, bid))

    if danger and tight_supply:
        if cindy_like:
            bid = min(budget, 114.0)
        else:
            bid = min(budget, max(52.0, highest_prev + 2.0, DAILY_SALARY * 0.8))
        return float(max(0.0, bid))

    if cindy_like:
        if ample_supply and hp >= 7 and no_water == 0:
            return float(min(budget, 3.0))
        if tight_supply:
            return float(min(budget, 18.0))
        return float(min(budget, 8.0))

    if highest_prev >= 80:
        if hp >= 7 and no_water == 0:
            return float(min(budget, 10.0))
        return float(min(budget, 60.0))

    if highest_prev > 0:
        if low_comp >= 2 and ample_supply:
            bid = max(12.0, highest_prev + 1.5)
        elif tight_supply:
            bid = max(28.0, highest_prev + 2.0)
        else:
            bid = max(18.0, highest_prev + 1.0)
        return float(min(budget, bid))

    if day <= 2:
        return float(min(budget, 14.0 if ample_supply else 20.0))
    if tight_supply:
        return float(min(budget, 24.0))
    return float(min(budget, 12.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Identify alive opponents
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Baseline: if low HP, bid to secure water
    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))

    # Contest level inferred from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Medium scenario supply: if enough supply, expect Cindy to keep bidding high.
    # Use a small overbid to beat the highest likely bidder.
    if supply >= 19.0:
        # If opponent already showed willingness to pay near ~DAILY_SALARY*1.25, match/overbid slightly.
        target = highest_prev_bid + 2.0
        # Cap to avoid bankrupting
        if hp <= 2.0:
            cap = DAILY_SALARY * 0.95
        else:
            cap = DAILY_SALARY * 0.75
        bid = min(budget, min(target, cap))
        # Ensure non-trivial bid
        if bid < DAILY_SALARY * 0.45:
            bid = min(budget, DAILY_SALARY * 0.55)
        return float(bid)

    # Lower supply: avoid bidding into a price war unless critical HP
    if hp <= 2.0:
        return float(min(budget, DAILY_SALARY * 0.9))

    # Otherwise bid around a mid-tier, slightly below yesterday contest
    if highest_prev_bid > 0.0:
        bid = min(budget, max(DAILY_SALARY * 0.5, highest_prev_bid * 0.8))
    else:
        bid = min(budget, DAILY_SALARY * 0.55)

    # Keep within reasonable range for this scenario
    if bid > DAILY_SALARY * 0.7:
        bid = DAILY_SALARY * 0.7
    return float(bid)

